import {useEffect,useRef,useState,type ReactNode} from 'react';
import {useQuery,useQueryClient} from '@tanstack/react-query';
import {useLocation,useNavigate} from 'react-router-dom';
import {useTranslation} from 'react-i18next';
import {ArrowUpRight,ArrowRight,ArrowLeft,Check,CheckCircle2,ChevronDown,ChevronRight,Cloud,Code2,Database,ExternalLink,Eye,EyeOff,FileCode2,Folder,FolderOpen,GitBranch,Globe2,History,Layers3,LoaderCircle,LockKeyhole,LogOut,MessageSquare,Monitor,Moon,Plus,Rocket,Send,Server,Settings2,ShieldCheck,Sparkles,Square,Sun,Terminal,TriangleAlert,X,RefreshCw,Workflow,KeyRound,BookOpen,Copy,Link2,Trash2} from 'lucide-react';
import {Select} from './Select';
import {call,external,errorText,native,pickFolder,subscribeRun} from './bridge';
import type {Account,AppStatus,ApprovalRequest,ChatMessage,DeploymentPlan,DeploymentRun,DomainRequest,DomainResult,PlanChoices,ProjectAnalysis,PlanningQuestion,Secrets,ServiceChoice,ServicePlan,VolumeMount,ProjectFixReview} from './types';

function Logo({small=false}:{small?:boolean}){return <span className={`logo ${small?'small':''}`} aria-hidden="true"><span/><i/></span>}
function Button({children,onClick,disabled=false,variant='primary',type='button',className=''}:{children:ReactNode;onClick?:()=>void;disabled?:boolean;variant?:string;type?:'button'|'submit';className?:string}){return <button className={`btn ${variant} ${className}`} type={type} disabled={disabled} onClick={onClick}>{children}</button>}
function Modal({children,title,onClose}:{children:ReactNode;title:string;onClose:()=>void}){const ref=useRef<HTMLDialogElement>(null);const {t}=useTranslation();useEffect(()=>{ref.current?.showModal();return()=>ref.current?.close()},[]);return <dialog ref={ref} className="modal" aria-label={title} onCancel={onClose}><button className="icon-button modal-close" onClick={onClose} aria-label={t('close')}><X size={20}/></button>{children}</dialog>}
function Notice({children,error=false}:{children:ReactNode;error?:boolean}){return <div className={`notice ${error?'error':''}`}><TriangleAlert size={18}/><div>{children}</div></div>}
function LocalizedMessage({text}:{text:string}){const {t,i18n}=useTranslation();if(i18n.language!=='fa'||/[\u0600-\u06FF]/.test(text))return <>{text}</>;let message=t('technicalIssue');if(text.includes('Unsupported deployment platform'))message=t('unsupportedPlatform');else if(text.includes('no compatible live plan'))message=t('noCompatiblePlan');else if(text.includes('Compose volume'))message=t('volumeNeedsChoice');else if(text.includes('Docker deployment requires a Dockerfile'))message=t('dockerfileRequired');return <span>{message}<details className="technical-detail"><summary>{t('technicalDetails')}</summary><code dir="auto">{text}</code></details></span>}
function insufficientStorage(message:string){return message.includes('not_enough_storage_space')}
function insufficientBalance(message:string){return /HTTP\s*402|insufficient balance|balance is insufficient|not enough balance/i.test(message)}
function PlatformIcon({kind,platform}:{kind:string;platform:string}){return <span className={`platform-icon ${kind==='database'?'purple':platform==='docker'?'cyan':'blue'}`}>{kind==='database'?<Database size={23}/>:platform==='docker'?<Layers3 size={23}/>:<Code2 size={23}/>}</span>}

export default function App(){
 const {t,i18n}=useTranslation();const nav=useNavigate();const location=useLocation();const cache=useQueryClient();
 const [theme,setTheme]=useState(localStorage.getItem('liara-theme')||'light');
 const [fixReview,setFixReview]=useState<ProjectFixReview|null>(null);const [storagePrompt,setStoragePrompt]=useState(false);
 const [errorPrompt,setErrorPrompt]=useState(false);const errorBanner=useRef<HTMLDivElement>(null);const reportedError=useRef('');
 const [chatOpen,setChatOpen]=useState(true);const [error,setError]=useState('');const [balancePrompt,setBalancePrompt]=useState(false);const [busy,setBusy]=useState('');
 const [project,setProject]=useState<ProjectAnalysis|null>(null);const [plan,setPlan]=useState<DeploymentPlan|null>(null);const [run,setRun]=useState<DeploymentRun|null>(null);
 const [deleteTarget,setDeleteTarget]=useState<{kind:'project'|'run';id:string;name:string;path?:string}|null>(null);
 const [questionsOpen,setQuestionsOpen]=useState(false);const [questions,setQuestions]=useState<PlanningQuestion[]>([]);const [advanced,setAdvanced]=useState(false);
 const [choices,setChoices]=useState<PlanChoices>({services:{},allowConfigRepairs:false});const [dirty,setDirty]=useState(false);
 const [secrets,setSecrets]=useState<Secrets>({});const [approval,setApproval]=useState<ApprovalRequest|null>(null);const [resumeId,setResumeId]=useState<string|null>(null);
 const [messages,setMessages]=useState<ChatMessage[]>([]);const [draft,setDraft]=useState('');const [chatBusy,setChatBusy]=useState(false);
 const [showLogs,setShowLogs]=useState(false);const chatEnd=useRef<HTMLDivElement>(null);
 const statusQuery=useQuery({queryKey:['status'],queryFn:async()=>{const status=await call<AppStatus>('app_status');if(!status.account){try{status.account=await call<Account|null>('restore_account')}catch(e){setError(errorText(e))}}return status}});
 const status=statusQuery.data;const account=status?.account||null;
 const projectsQuery=useQuery({queryKey:['projects',account?.id],queryFn:()=>call<ProjectAnalysis[]>('list_projects'),enabled:!!account});
 const runsQuery=useQuery({queryKey:['runs',account?.id],queryFn:()=>call<DeploymentRun[]>('list_runs'),enabled:!!account,refetchInterval:run?.status==='running'?5000:false});
 const storageRecovery=useQuery({queryKey:['storage-recovery',run?.id,run?.updatedAt,i18n.language],queryFn:()=>call<DeploymentPlan>('prepare_storage_recovery',{runId:run!.id,language:i18n.language}),enabled:storagePrompt&&!!run&&run.status!=='running',retry:false,refetchOnWindowFocus:false,staleTime:Infinity});
 useEffect(()=>{document.documentElement.lang=i18n.language;document.documentElement.dir=i18n.language==='fa'?'rtl':'ltr';localStorage.setItem('liara-language',i18n.language)},[i18n.language]);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('liara-theme',theme)},[theme]);
 useEffect(()=>{let dispose:(()=>void)|undefined;let dead=false;subscribeRun(r=>{setRun(current=>current?.id===r.id?r:current);if(r.status!=='running')void cache.invalidateQueries({queryKey:['runs']});}).then(fn=>{if(dead)fn();else dispose=fn});return()=>{dead=true;dispose?.()}},[cache]);
 useEffect(()=>{chatEnd.current?.scrollIntoView({behavior:'smooth',block:'nearest'})},[messages,chatBusy]);
 useEffect(()=>{if(runsQuery.data&&run){const latest=runsQuery.data.find(r=>r.id===run.id);if(latest&&latest.updatedAt>run.updatedAt)setRun(latest)}},[runsQuery.data,run]);
 useEffect(()=>{if(error){setStoragePrompt(insufficientStorage(error));setErrorPrompt(true);errorBanner.current?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}},[error]);
 useEffect(()=>{if(run?.status!=='failed')return;const event=run.events.slice().reverse().find(e=>e.level==='error');if(!event)return;const key=`${run?.id}:${event.at}:${event.message}`;if(reportedError.current===key)return;reportedError.current=key;setApproval(null);setError(event.message);if(insufficientBalance(event.message))setBalancePrompt(true)},[run]);
 useEffect(()=>{if(!plan||location.pathname!=='/review')return;let active=true;call<Secrets>('plan_environment',{planId:plan.id}).then(local=>{if(active)setSecrets(current=>Object.fromEntries(plan.services.map(s=>[s.id,{...local[s.id],...current[s.id]}])))}).catch(e=>{if(active)setError(errorText(e))});return()=>{active=false}},[plan?.id,resumeId,location.pathname]);
 const setAccount=(account:Account|null)=>cache.setQueryData<AppStatus>(['status'],old=>({...old!,agent:old?.agent||{configured:false},version:old?.version||'0.1.0',account}));
 const work=async(label:string,fn:()=>Promise<void>)=>{setBusy(label);setError('');try{await fn()}catch(e){const message=errorText(e);if(insufficientBalance(message))setBalancePrompt(true);setError(message)}finally{setBusy('')}};
 const money=(n:number|null|undefined)=>n==null?t('unknown'):new Intl.NumberFormat(i18n.language==='fa'?'fa-IR':'en-US',{maximumFractionDigits:0}).format(n);
 const chooseProject=()=>work('scan',async()=>{const path=await pickFolder();if(!path)return;await scan(path)});
 const scan=async(path:string)=>{const p=await call<ProjectAnalysis>('scan_project',{path,language:i18n.language});setProject(p);setPlan(null);setRun(null);setSecrets({});setChoices({services:{},allowConfigRepairs:false});setMessages([]);setResumeId(null);await cache.invalidateQueries({queryKey:['projects']});nav('/project')};
 const openProject=(p:ProjectAnalysis)=>{setProject(p);setPlan(null);setRun(null);setSecrets({});setResumeId(null);setChoices({services:{},allowConfigRepairs:false});nav('/project')};
 const makePlan=(planningChoices:PlanChoices)=>work('plan',async()=>{if(!project)return;const p=await call<DeploymentPlan>('prepare_plan',{projectId:project.id,choices:planningChoices,language:i18n.language});setPlan(p);setDirty(false);setResumeId(null);setChoices({answers:planningChoices.answers,guided:planningChoices.guided,services:Object.fromEntries(p.services.map(s=>[s.id,{name:s.name,planId:s.planId,planLocked:planningChoices.services[s.id]?.planLocked||false,bundleId:s.bundleId,existingId:s.existingId||undefined,port:s.port,version:s.version||undefined,bindings:s.bindings,volumes:Object.fromEntries((s.volumes||[]).map(v=>[v.id,{resolution:v.resolution||undefined,diskName:v.diskName||undefined,sizeGb:v.sizeGb||undefined}]))}])),network:p.network||undefined,allowConfigRepairs:p.allowConfigRepairs});nav('/review');await cache.invalidateQueries({queryKey:['status']})});
 const prepare=()=>makePlan(choices);
 const beginQuestions=()=>work('questions',async()=>{if(!project)return;setQuestions([]);setQuestionsOpen(true);try{setQuestions(await call<PlanningQuestion[]>('planning_questions',{projectId:project.id,language:i18n.language}))}catch(e){setQuestionsOpen(false);throw e}});
 const answerQuestions=(answers:Record<string,string>)=>{setQuestionsOpen(false);setAdvanced(false);const next={...choices,answers,guided:true};setChoices(next);void makePlan(next)};
 const edit=(id:string,patch:Partial<ServiceChoice>)=>{setChoices(v=>({...v,services:{...v.services,[id]:{...v.services[id],bindings:v.services[id]?.bindings||{},...patch}}}));setDirty(true)};
 const requestApproval=()=>work('approval',async()=>{if(!plan)return;setApproval(await call<ApprovalRequest>('request_approval',{planId:plan.id,secrets,resumeId}))});
 const deploy=()=>work('deploy',async()=>{if(!approval)return;const r=await call<DeploymentRun>('start_deployment',{approvalId:approval.id,revision:approval.revision});setApproval(null);setSecrets({});setRun(r);nav('/run');await cache.invalidateQueries({queryKey:['runs']})});
 const openRun=(r:DeploymentRun)=>{setRun(r);setPlan(r.plan);setProject(projectsQuery.data?.find(p=>p.id===r.plan.projectId)||null);setSecrets({});setResumeId(null);nav('/run')};
 const resume=()=>work('resume',async()=>{if(!run)return;const storageError=insufficientStorage(run.events.slice().reverse().find(e=>e.level==='error')?.message||'');const target=storageError?await call<DeploymentPlan>('prepare_storage_recovery',{runId:run.id,language:i18n.language}):run.plan;setPlan(target);setResumeId(run.id);setDirty(false);try{setApproval(await call<ApprovalRequest>('request_approval',{planId:target.id,secrets:{},resumeId:run.id}))}catch(e){nav('/review');throw e}});
 const approveStorageRecovery=()=>work('approval',async()=>{if(!run||!storageRecovery.data)return;setStoragePrompt(false);setErrorPrompt(false);setPlan(storageRecovery.data);setResumeId(run.id);setDirty(false);try{setApproval(await call<ApprovalRequest>('request_approval',{planId:storageRecovery.data.id,secrets:{},resumeId:run.id}))}catch(e){nav('/review');throw e}});
 const inspectFix=()=>work('source-fix',async()=>{const target=run?.plan||plan;if(!target)return;setErrorPrompt(false);setFixReview(await call<ProjectFixReview>('propose_project_fix',{planId:target.id,runId:run?.plan.id===target.id?run.id:null,language:i18n.language}))});
 const replanExisting=async()=>{
  const previous=run?.plan||plan;if(!previous)return;
  const reuse:PlanChoices={...choices,guided:true,network:run?.networkId||previous.network||undefined,services:Object.fromEntries(previous.services.map(service=>[service.id,{name:service.name,planId:service.planId,planLocked:choices.services[service.id]?.planLocked||false,bundleId:service.bundleId,port:service.port,version:service.version||undefined,existingId:run?.resources.find(r=>r.serviceId===service.id)?.resourceId||service.existingId||undefined,bindings:service.bindings,volumes:Object.fromEntries((service.volumes||[]).map(v=>[v.id,{resolution:v.resolution||undefined,diskName:v.diskName||undefined,sizeGb:v.sizeGb||undefined}]))}]))};
  setChoices(reuse);setResumeId(null);setRun(null);setDirty(false);setAdvanced(true);
  const updated=await call<DeploymentPlan>('prepare_plan',{projectId:previous.projectId,choices:reuse,language:i18n.language});
  setPlan(updated);setSecrets({});nav('/review');await cache.invalidateQueries({queryKey:['projects']});return updated;
 };
 const acceptFix=()=>work('apply-fix',async()=>{
  if(!fixReview)return;const accepted=fixReview;setFixReview(null);
  setProject(await call<ProjectAnalysis>('apply_project_fix',{approvalId:accepted.id,revision:accepted.revision}));
  const updated=await replanExisting();if(!updated)return;
  const values=await call<Secrets>('plan_environment',{planId:updated.id});setSecrets(values);
  const missing=updated.services.some(s=>s.envKeys.some(k=>!s.bindings[k]&&!values[s.id]?.[k]?.trim()));
  if(!updated.blockers.length&&!missing)setApproval(await call<ApprovalRequest>('request_approval',{planId:updated.id,secrets:values,resumeId:null}));
 });
 const send=async(text=draft)=>{if(!text.trim()||chatBusy||!account)return;const next:ChatMessage[]=[...messages,{role:'user',content:text.trim()}];setMessages(next);setDraft('');setChatBusy(true);try{const content=await call<string>('chat_agent',{projectId:project?.id||null,runId:run?.id||null,messages:next,language:i18n.language});setMessages([...next,{role:'assistant',content}])}catch(e){setError(errorText(e))}finally{setChatBusy(false)}};
 const openExternal=(url:string)=>{void external(url).catch(e=>setError(errorText(e)))};
 const currentStep=!account?0:location.pathname==='/review'?2:location.pathname==='/run'?3:1;
 const disabled=!!busy;const total=plan?.services.reduce<number|null>((sum,s)=>sum==null||s.monthlyPrice==null?null:sum+s.monthlyPrice,0);
 const missing=plan?.services.some(s=>(!resumeId||!run?.resources.some(r=>r.serviceId===s.id&&r.phase==='verified'))&&s.envKeys.some(k=>!s.bindings[k]&&!secrets[s.id]?.[k]?.trim()));
 const removeRecord=()=>work('remove-record',async()=>{if(!deleteTarget)return;const target=deleteTarget;await call(target.kind==='project'?'remove_recent_project':'delete_deployment',target.kind==='project'?{projectId:target.id}:{runId:target.id});setDeleteTarget(null);if(target.kind==='run'&&run?.id===target.id){setRun(null);setPlan(null);setApproval(null);setResumeId(null);setSecrets({});nav('/deployments')}else if(target.kind==='project'&&project?.path===target.path&&location.pathname!=='/run'){setProject(null);setPlan(null);setApproval(null);setSecrets({});nav('/')}await cache.invalidateQueries({queryKey:[target.kind==='project'?'projects':'runs']})});
 const recent=projectsQuery.data?.filter((p,i,all)=>all.findIndex(x=>x.path===p.path)===i)||[];

 return <div className={`app-shell ${chatOpen?'with-assistant':''}`}>
  <aside className="sidebar">
   <button className="brand" onClick={()=>nav('/')}><Logo/><span>Liara<span className="brand-secondary">Launch</span></span></button>
   <button className="new-project" disabled={!account||disabled} onClick={chooseProject}><Plus size={18}/>{t('newProject')}<span className="shortcut">＋</span></button>
   <div className="nav-label">{t('workspace')}</div>
   <nav>
    <button className={['/','/project','/review','/run'].includes(location.pathname)?'active':''} onClick={()=>nav('/')}><Layers3 size={19}/>{t('projects')}</button>
    <button className={location.pathname==='/deployments'?'active':''} onClick={()=>nav('/deployments')}><History size={19}/>{t('deployments')}{(runsQuery.data?.length||0)>0&&<span className="count">{runsQuery.data?.length}</span>}</button>
   </nav>
   {recent.length>0&&<><div className="nav-label recent-label">{t('recentProjects')}</div><div className="project-nav">{recent.slice(0,6).map(p=><div className="project-nav-row" key={p.id}><button className={`project-open ${project?.id===p.id?'selected':''}`} onClick={()=>openProject(p)}><span className="project-dot"/><span>{p.name}</span></button><button className="icon-button remove-project" aria-label={`${t('removeProject')}: ${p.name}`} disabled={disabled} onClick={()=>setDeleteTarget({kind:'project',id:p.id,name:p.name,path:p.path})}><Trash2 size={15}/></button></div>)}</div></>}
   <div className="sidebar-bottom"><button onClick={()=>openExternal('https://docs.liara.ir/')}><BookOpen size={18}/>{t('help')}<ArrowUpRight size={14}/></button><button className={location.pathname==='/settings'?'active':''} onClick={()=>nav('/settings')}><Settings2 size={18}/>{t('settings')}</button>
    <div className="account-mini"><div className="avatar">{account?.name?.charAt(0)||<Cloud size={19}/>}</div><div><strong>{account?.name||t('account')}</strong><span><i className={`status-dot ${account?'online':''}`}/>{account?t('connected'):t('notConnected')}</span></div>{account&&<button className="icon-button" aria-label={t('refresh')} onClick={()=>work('refresh',async()=>{setAccount(await call<Account>('refresh_account'))})}><RefreshCw size={15}/></button>}</div>
   </div>
  </aside>
  <div className="workspace-shell">
   <header className="topbar"><div className="breadcrumbs"><span>{t('workspace')}</span><ChevronRight size={14}/><strong>{location.pathname==='/settings'?t('settings'):location.pathname==='/deployments'?t('deployments'):project?.name||t('newDeployment')}</strong></div><div className="toolbar"><span className="desktop-badge"><Monitor size={13}/>{t('local')}</span><button className="language-button" onClick={()=>{localStorage.setItem('liara-language-selected','yes');void i18n.changeLanguage(i18n.language==='fa'?'en':'fa')}} aria-label={t('language')}><Globe2 size={15}/>{i18n.language==='fa'?'EN':'فا'}</button><button className="icon-button" aria-label={t('theme')} onClick={()=>setTheme(theme==='light'?'dark':'light')}>{theme==='light'?<Moon size={17}/>:<Sun size={17}/>}</button><span className="toolbar-divider"/><button className={`icon-button ${chatOpen?'selected':''}`} aria-label={t(chatOpen?'hideAssistant':'showAssistant')} onClick={()=>setChatOpen(!chatOpen)}><MessageSquare size={19}/></button></div></header>
   {!native&&!window.__LIARA_TEST_INVOKE__&&<div className="preview-banner"><Monitor size={14}/>{t('nativePreview')}</div>}
   {error&&<div ref={errorBanner} className="error-banner" role="alert" tabIndex={-1}><TriangleAlert size={19}/><div><strong>{t('error')}</strong>{i18n.language==='fa'?<><p>{t(insufficientStorage(error)?'storageLowBody':'operationFailed')}</p><details className="technical-detail"><summary>{t('technicalDetails')}</summary><code dir="auto">{error}</code></details></>:<p>{error}</p>}</div><button className="icon-button" aria-label={t('dismiss')} onClick={()=>setError('')}><X size={17}/></button></div>}
   {error&&errorPrompt&&!balancePrompt&&!storagePrompt&&<Modal title={t('error')} onClose={()=>setErrorPrompt(false)}><div className="modal-symbol balance-warning"><TriangleAlert size={27}/></div><h2>{t('error')}</h2><p>{t('operationFailed')}</p><details className="technical-detail"><summary>{t('technicalDetails')}</summary><code dir="auto">{error}</code></details><div className="modal-actions">{run?.status==='failed'&&!insufficientBalance(error)&&<Button variant="secondary" disabled={!!busy} onClick={inspectFix}><Sparkles size={16}/>{t('reviewProjectFix')}</Button>}<Button onClick={()=>{setErrorPrompt(false);errorBanner.current?.scrollIntoView({block:'start'})}}>{t('close')}</Button></div></Modal>}
   {balancePrompt&&<Modal title={t('balanceLowTitle')} onClose={()=>{setBalancePrompt(false);setErrorPrompt(false)}}><div className="modal-symbol balance-warning"><TriangleAlert size={27}/></div><h2>{t('balanceLowTitle')}</h2><p>{t('balanceLowBody')}</p><div className="modal-actions"><Button variant="secondary" onClick={()=>{setBalancePrompt(false);setErrorPrompt(false)}}>{t('close')}</Button><Button onClick={()=>openExternal('https://console.liara.ir/')}><ExternalLink size={15}/>{t('topUpBalance')}</Button></div></Modal>}
   {storagePrompt&&<Modal title={t('storageLowTitle')} onClose={()=>{setStoragePrompt(false);setErrorPrompt(false)}}><div className="modal-symbol"><Database size={27}/></div><h2>{t('storageLowTitle')}</h2><p>{t('storageLowBody')}</p>{storageRecovery.isFetching?<p role="status"><LoaderCircle className="spin" size={18}/> {t('findingStoragePlan')}</p>:storageRecovery.data?<div className="storage-recommendation"><p>{storageRecovery.data.summary}</p>{storageRecovery.data.services.filter(s=>s.resize).map(s=><section key={s.id}><h3 dir="ltr">{s.name}</h3><p>{t('storagePlanCapacity',{required:money(s.resize!.requiredGb),capacity:money(s.resize!.targetCapacityGb)})}</p><div className="storage-plan-choice"><span dir="ltr">{s.resize!.fromPlanId} → {s.planId}</span><strong>{money(s.resize!.targetMonthlyPrice)} {t('toman')} {t('month')}</strong></div><p className="muted">{t('storagePreviousCost',{price:money(s.resize!.fromMonthlyPrice)})}</p></section>)}</div>:storageRecovery.error?<Notice error><LocalizedMessage text={errorText(storageRecovery.error)}/></Notice>:null}<p>{t('storagePreserved')}</p><details className="technical-detail"><summary>{t('technicalDetails')}</summary><code dir="auto">{error}</code></details><div className="modal-actions"><Button variant="secondary" onClick={()=>{setStoragePrompt(false);setErrorPrompt(false)}}>{t('close')}</Button>{storageRecovery.data&&<Button disabled={!!busy||storageRecovery.isFetching} onClick={approveStorageRecovery}><Rocket size={16}/>{t('reviewStorageUpgrade')}</Button>}{!storageRecovery.data&&!storageRecovery.isFetching&&<Button variant="secondary" onClick={()=>openExternal('https://console.liara.ir/')}><ExternalLink size={16}/>{t('openConsole')}</Button>}</div></Modal>}
   {fixReview&&<Modal title={t('projectFixTitle')} onClose={()=>setFixReview(null)}><div className="modal-symbol"><FileCode2 size={27}/></div><h2>{t('projectFixTitle')}</h2><p>{fixReview.explanation}</p>{fixReview.changes.length>0?<><p>{t('projectFixDisclosure')}</p><div className="source-diffs">{fixReview.changes.map(change=><section key={change.path}><h3><code dir="ltr">{change.path}</code></h3><p>{change.reason}</p><div className="source-diff" dir="ltr" aria-label={change.path}><div className="diff-before"><strong>{t('beforeChange')}</strong><pre>{change.before.split('\n').map(line=>'- '+line).join('\n')}</pre></div><div className="diff-after"><strong>{t('afterChange')}</strong><pre>{change.after.split('\n').map(line=>'+ '+line).join('\n')}</pre></div></div></section>)}</div><div className="modal-actions"><Button variant="secondary" onClick={()=>setFixReview(null)}>{t('cancel')}</Button><Button disabled={!!busy} onClick={acceptFix}>{t('applyProjectFix')}</Button></div></>:<div className="modal-actions"><Button onClick={()=>setFixReview(null)}>{t('close')}</Button></div>}</Modal>}
   <main className="main-content">
    {location.pathname==='/settings'?<SettingsView account={account} status={status} theme={theme} setTheme={setTheme} money={money} disconnect={()=>work('disconnect',async()=>{await call('disconnect_account');setAccount(null);setProject(null);setPlan(null);setRun(null);setSecrets({});setMessages([]);cache.removeQueries({queryKey:['projects']});cache.removeQueries({queryKey:['runs']});nav('/')})}/>:location.pathname==='/deployments'?<>
      <PageHeading eyebrow={t('deployments')} title={t('historyTitle')} description={t('historyDescription')}/>
      {!runsQuery.data?.length?<div className="empty-state"><div className="empty-icon"><Rocket size={34}/></div><h2>{t('noRuns')}</h2><p>{t('noRunsHint')}</p><Button onClick={()=>nav('/')}>{t('start')}<ArrowRight size={16}/></Button></div>:<div className="history-list">{runsQuery.data.map(r=><div className="history-row" key={r.id}><button className="history-card" onClick={()=>openRun(r)}><span className={`history-icon ${r.status==='succeeded'?'success':''}`}>{r.status==='succeeded'?<CheckCircle2 size={23}/>:<Rocket size={23}/>}</span><div><h3>{r.plan.services.find(s=>s.kind==='app')?.name||r.id.slice(0,8)}</h3><p>{new Date(r.startedAt).toLocaleString(i18n.language==='fa'?'fa-IR':'en-US')}</p></div><span className={`pill ${r.status==='succeeded'?'green':'amber'}`}>{t(r.status)}</span><ChevronRight size={17}/></button><button className="icon-button delete-history" disabled={disabled||r.status==='running'} title={r.status==='running'?t('stopBeforeDelete'):t('deleteDeployment')} aria-label={`${t('deleteDeployment')}: ${r.plan.services.find(s=>s.kind==='app')?.name||r.id}`} onClick={()=>setDeleteTarget({kind:'run',id:r.id,name:r.plan.services.find(s=>s.kind==='app')?.name||r.id})}><Trash2 size={18}/></button></div>)}</div>}
    </>:<>
      <div className="stepper">{['stepConnect','stepProject','stepReview','stepDeploy'].map((key,i)=><div key={key} className={`step ${i===currentStep?'current':i<currentStep?'complete':''}`}><span>{i<currentStep?<Check size={13}/>:i+1}</span><label>{t(key)}</label>{i<3&&<i/>}</div>)}</div>
      {busy==='scan'||busy==='plan'?<div className="analysis-loading"><div className="scan-visual"><div/><FolderOpen size={44}/><Sparkles size={21}/></div><span className="eyebrow">LIARA INTELLIGENCE</span><h1>{t(busy==='scan'?'scanning':'planning')}</h1><p>{t(busy==='scan'?'scanHint':'planningHint')}</p><div className="loading-bar"><span/></div><div className="loading-chips"><span><FileCode2 size={15}/>{t('files')}</span><span><Server size={15}/>{t('services')}</span><span><ShieldCheck size={15}/>{t('secure')}</span></div></div>:
       !account?<ConnectView onConnect={(token,teamId,remember)=>work('connect',async()=>{setAccount(await call<Account>('connect_account',{token,teamId:teamId??null,remember}));nav('/')})} onExternal={openExternal} busy={busy==='connect'}/>:
       location.pathname==='/review'&&plan?<>
        <PageHeading eyebrow={resumeId?t('resume'):t('recommended')} title={t('reviewTitle')} description={t('reviewShortDescription')}/>
        {plan.services.some(s=>s.resize)&&<section className="panel storage-recommendation"><h3>{t('storageUpgradeRecommended')}</h3>{plan.services.filter(s=>s.resize).map(s=><p key={s.id}>{s.rationale}</p>)}</section>}{plan.blockers.length>0&&<div className="project-fix-action"><Button variant="secondary" disabled={disabled} onClick={inspectFix}><Sparkles size={17}/>{t('reviewProjectFix')}</Button></div>}{plan.blockers.length>0&&(advanced?<Notice error><strong>{t('blocked')}</strong><ul>{plan.blockers.map((x,i)=><li key={i}><LocalizedMessage text={x}/></li>)}</ul></Notice>:<section className="panel readiness-note"><TriangleAlert size={22}/><div><h3>{t('setupNeedsHelp')}</h3><p>{t('setupNeedsHelpHint')}</p><Button variant="secondary" onClick={()=>setAdvanced(true)}>{t('reviewSettings')}</Button></div></section>)}
        {!advanced&&<section className="panel simple-summary"><div className="section-title"><Sparkles size={20}/><h3>{t('setupReady')}</h3></div><p>{t('setupReadyHint')}</p><ul>{plan.services.map(s=><li key={s.id}><strong>{s.name}</strong><span>{s.rationale}</span>{s.volumes.filter(v=>v.resolution==='disk').map(v=><span key={v.id}>{t('fileSpace')}: {new Intl.NumberFormat(i18n.language).format(v.sizeGb||0)} {t('gigabytes')}</span>)}</li>)}</ul></section>}
        <div className={advanced?'review-layout':'review-layout simple-review'}><div className="service-plans">{plan.services.map(s=><ServiceCard key={s.id} service={s} account={account} choice={choices.services[s.id]} onEdit={patch=>edit(s.id,patch)} money={money} locked={!!resumeId}/>)}
         <section className="panel network-panel"><div className="section-title"><Workflow size={19}/><h3>{t('network')}</h3></div><Select aria-label={t('network')} value={choices.network||plan.network||''} disabled={!!resumeId} onChange={e=>{setChoices(c=>({...c,network:e.target.value}));setDirty(true)}}>{account.networks.map(n=><option key={String(n._id)} value={String(n._id)}>{String(n.name)}</option>)}<option value={`new:${project?.name.toLowerCase().replace(/[^a-z0-9-]/g,'-')||'project'}-network`}>{t('newNetwork')}</option></Select></section>
        </div><aside className="cost-card"><span className="eyebrow">{t('estimate')}</span><div className="cost-number">{money(total)}<span>{t('toman')}</span></div><p className="muted">{t('month')}</p><div className="cost-lines">{plan.services.map(s=><div key={s.id}><span>{s.name}</span><strong>{s.existingId&&!s.resize?'—':money(s.monthlyPrice)}</strong></div>)}</div><p className="fine-print">{t('estimateHint')}</p>{plan.services.some(s=>(s.volumes||[]).some(v=>v.resolution==='disk'))&&<p className="disk-cost-note">{t('diskCostNotIncluded')}</p>}<div className="cost-note"><ShieldCheck size={18}/><span>{t('controlDesc')}</span></div></aside></div>
        {(advanced||missing)&&plan.services.some(s=>s.envKeys.length>0)&&<details className="panel env-panel" open><summary className="section-title"><KeyRound size={20}/><h3>{t('variables')}</h3><ChevronDown size={18}/></summary><p>{t('variablesHint')}</p>{plan.services.map(s=><div key={s.id}>{s.envKeys.length>0&&<h4>{s.name}</h4>}{s.envKeys.map(key=><div className="env-row" key={key}><label htmlFor={`${s.id}-${key}`} className="mono">{key}</label>{<input id={`${s.id}-${key}`} dir="ltr" type="text" autoComplete="off" spellCheck={false} value={secrets[s.id]?.[key]||''} placeholder={s.bindings[key]?t('automatic'):s.localEnvKeys?.includes(key)?t('fromLocalEnv'):t('secretValue')} onChange={e=>setSecrets(values=>({...values,[s.id]:{...values[s.id],[key]:e.target.value}}))}/>}</div>)}</div>)}<p className="fine-print"><LockKeyhole size={13}/>{t('noSecretPersistence')}</p></details>}
        {plan.warnings.length>0&&<details className="panel details-panel"><summary>{t('warnings')} <span className="count">{plan.warnings.length}</span><ChevronDown size={16}/></summary><ul>{plan.warnings.map((w,i)=><li key={i}><LocalizedMessage text={w}/></li>)}</ul></details>}
        <div className="customize-deployment"><Button variant="secondary" disabled={disabled} onClick={()=>{if(advanced&&dirty)void prepare();setAdvanced(!advanced)}}><Settings2 size={17}/>{t(advanced?'simpleSettings':'changeSettings')}</Button><p>{t('customizeHint')}</p></div>
        <div className="action-footer"><Button variant="ghost" onClick={()=>nav(resumeId?'/run':'/project')}><ArrowLeft size={16}/>{t('back')}</Button><div>{!resumeId&&advanced&&<Button variant="secondary" onClick={prepare} disabled={disabled}>{t('regenerate')}<RefreshCw size={16}/></Button>}<Button onClick={requestApproval} disabled={disabled||dirty||!!missing||plan.blockers.length>0}>{busy==='approval'?<LoaderCircle className="spin" size={17}/>:<Rocket size={17}/>} {t(resumeId?'resume':advanced?'reviewDeploy':'deployProject')}</Button></div></div>
       </>:location.pathname==='/run'&&run?<>
        <PageHeading eyebrow={t(run.status)} title={t(run.status==='succeeded'?'liveTitle':run.status==='running'?'launchTitle':'failedTitle')} description={t(run.status==='succeeded'?'liveDescription':run.status==='running'?'launchDescription':'failedDescription')}/>
        {run.status==='succeeded'&&<div className="live-banner"><div className="live-orb"><Check size={31}/></div><div><span>{t('connected')}</span><h2>{run.plan.services.find(s=>s.kind==='app')?.name}</h2></div><Sparkles size={38}/></div>}
        <div className="run-resources">{run.resources.map(r=>{const s=run.plan.services.find(s=>s.id===r.serviceId)!;return <div className="resource-row panel" key={r.serviceId}><PlatformIcon kind={s.kind} platform={s.platform}/><div><h3>{s.name}</h3><p>{s.platform} {r.releaseId&&<span className="mono">· {r.releaseId.slice(0,8)}</span>}</p></div><span className={`pill ${['ready','verified'].includes(r.phase)?'green':'blue'}`}>{t(r.phase,{defaultValue:r.phase})}</span>{r.url&&<button className="icon-button" title={t('visit')} onClick={()=>openExternal(r.url!)}><ArrowUpRight size={18}/></button>}</div>})}</div>
        {run.status!=='running'&&run.status!=='succeeded'&&<Notice>{t('preserved')}</Notice>}
        <section className="panel activity-panel"><div className="section-title"><h3>{t('activity')}</h3>{run.status==='running'&&<LoaderCircle size={17} className="spin"/>}<button className="text-button" onClick={()=>setShowLogs(!showLogs)}>{t(showLogs?'hideLogs':'showLogs')}</button></div><div className="timeline">{run.events.filter(e=>showLogs||e.level!=='log').map((e,i)=><div key={`${e.at}-${i}`} className={`timeline-event ${e.level}`}><span className="timeline-dot">{e.level==='success'?<Check size={11}/>:e.level==='error'?<X size={11}/>:null}</span><time>{new Date(e.at).toLocaleTimeString(i18n.language==='fa'?'fa-IR':'en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time>{e.level==='error'&&i18n.language==='fa'?<div><pre>{t('operationFailed')}</pre><details className="technical-detail"><summary>{t('technicalDetails')}</summary><pre dir="auto">{e.message}</pre></details></div>:<pre dir="auto">{e.message}</pre>}</div>)}{run.events.length===0&&<p className="muted">{t('noActivity')}</p>}</div></section>
        <div className="action-footer"><Button variant="secondary" onClick={inspectFix} disabled={disabled||chatBusy||run.status==='succeeded'||run.status==='running'}><Sparkles size={17}/>{t('askAssistant')}</Button>{run.status==='running'?<Button variant="secondary" onClick={()=>work('stop',async()=>{await call('stop_deployment',{runId:run.id})})} disabled={disabled}><Square size={14}/>{t('stop')}</Button>:run.status==='succeeded'?<Button onClick={()=>work('scan',async()=>{if(project)await scan(project.path);else nav('/')})}><RefreshCw size={16}/>{t('redeploy')}</Button>:<Button onClick={resume}>{t('resume')}<ArrowRight size={17}/></Button>}</div>
        {run.resources.some(r=>r.url)&&<DomainPanel run={run} work={work} busy={busy}/>}
       </>:location.pathname==='/project'&&project?<>
        <PageHeading eyebrow={t('detected')} title={project.name} description={project.path}/>
        <div className="project-stats"><div><Layers3 size={19}/><strong>{project.services.length}</strong><span>{t('services')}</span></div><div><FileCode2 size={19}/><strong>{project.fileCount}</strong><span>{t('files')}</span></div><div><GitBranch size={19}/><strong>{project.gitBranch||'—'}</strong><span>{t(project.gitBranch?(project.gitDirty?'uncommitted':'branch'):'noGit')}</span></div></div>
        <div className="detected-list">{project.services.map(s=><section className="panel detected-card" key={s.id}><div className="detected-title"><PlatformIcon kind={s.kind} platform={s.platform}/><div><h3>{s.name}</h3><p>{s.platform} <span>·</span> <code>{s.root}</code></p></div><span className="pill green"><Check size={12}/>{t('detected')}</span></div><div className="evidence-chips">{s.evidence.map((e,i)=><span key={i}><FileCode2 size={13}/>{e}</span>)}</div>{s.envKeys.length>0&&<p className="detected-env"><KeyRound size={14}/>{s.envKeys.length} {t('requirements')}</p>}{s.warnings.map((w,i)=><p className="inline-warning" key={i}><TriangleAlert size={15}/>{w}</p>)}</section>)}</div>
        {project.warnings.map((w,i)=><Notice key={i}>{w}</Notice>)}
        {!status?.agent.configured&&<Notice><strong>{t('notConfigured')}</strong><p>{t('providerSetup')}</p><button className="text-button" onClick={()=>nav('/settings')}>{t('settings')}<ArrowUpRight size={14}/></button></Notice>}
        <div className="action-footer"><Button variant="secondary" disabled={disabled} onClick={()=>work('scan',()=>scan(project.path))}><RefreshCw size={16}/>{t('rescan')}</Button><Button disabled={disabled||project.services.length===0} onClick={beginQuestions}><Sparkles size={17}/>{t('analyzePlan')}</Button></div>
       </>:<>
        <PageHeading eyebrow={t('connectionReady')} title={t('selectTitle')} description={t('selectDescription')}/>
        <button className="folder-picker" onClick={chooseProject} disabled={disabled}><span className="folder-art"><FolderOpen size={52}/><i><Plus size={17}/></i></span><h2>{t('folderDrop')}</h2><p>{t('folderHint')}</p><span className="btn primary"><Folder size={17}/>{t('selectFolder')}</span><span className="fine-print">{t('supported')}</span></button>
        <div className="privacy-note"><ShieldCheck size={17}/>{t('folderPrivate')}</div>
        {recent.length>0&&<section className="recent-section"><div className="section-title"><h3>{t('recentProjects')}</h3><span className="count">{recent.length}</span></div><div className="recent-grid">{recent.slice(0,4).map(p=><div className="recent-card-wrapper" key={p.id}><button className="recent-card" onClick={()=>openProject(p)}><div><Folder size={21}/></div><h3>{p.name}</h3><p>{p.services.map(s=>s.platform).join(' · ')}</p></button><button className="icon-button remove-record" aria-label={`${t('removeProject')}: ${p.name}`} disabled={disabled} onClick={()=>setDeleteTarget({kind:'project',id:p.id,name:p.name,path:p.path})}><Trash2 size={17}/></button></div>)}</div></section>}
       </>}
    </>}
   </main><footer className="workspace-footer"><span><ShieldCheck size={13}/>{t('noMonitoring')}</span><span>Liara Launch <span className="mono">v0.1</span></span></footer>
  </div>
  {chatOpen&&<aside className="assistant-panel"><div className="assistant-header"><span className="assistant-mark"><Sparkles size={19}/></span><div><h3>{t('assistant')}</h3><p><i className="status-dot online"/>{t('assistantHint')}</p></div><button className="icon-button" aria-label={t('hideAssistant')} onClick={()=>setChatOpen(false)}><X size={17}/></button></div><div className="assistant-context"><span><Folder size={13}/>{project?.name||t('newDeployment')}</span><span className="context-dot"/>{status?.agent.model||'AI'}</div><div className="chat-messages"><div className="assistant-message intro-message"><span className="message-avatar"><Sparkles size={16}/></span><div><span className="message-name">Liara</span><p>{t('assistantWelcome')}</p></div></div>{messages.map((m,i)=><div key={i} className={`${m.role}-message`}>{m.role==='assistant'&&<span className="message-avatar"><Sparkles size={16}/></span>}<div>{m.role==='assistant'&&<span className="message-name">Liara</span>}<p dir="auto">{m.content}</p></div></div>)}{chatBusy&&<div className="assistant-message"><span className="message-avatar"><Sparkles size={16}/></span><span className="thinking"><i/><i/><i/>{t('thinking')}</span></div>}<div ref={chatEnd}/></div><div className="chat-bottom">{messages.length===0&&<div className="assistant-tip"><ShieldCheck size={18}/><p>{t('controlDesc')}</p></div>}<form className="chat-input" onSubmit={e=>{e.preventDefault();void send()}}><textarea dir={i18n.language==='fa'?'rtl':'ltr'} value={draft} onChange={e=>setDraft(e.target.value)} placeholder={t('chatPlaceholder')} aria-label={t('chatPlaceholder')} rows={2} disabled={!account||chatBusy} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();void send()}}}/><div><span><LockKeyhole size={12}/>{t('secure')}</span><button type="submit" aria-label={t('send')} disabled={!account||!draft.trim()||chatBusy}><Send size={16}/></button></div></form></div></aside>}
  {deleteTarget&&<Modal title={t(deleteTarget.kind==='project'?'removeProject':'deleteDeployment')} onClose={()=>{if(!busy)setDeleteTarget(null)}}><div className="modal-symbol balance-warning"><Trash2 size={26}/></div><h2>{t(deleteTarget.kind==='project'?'removeProject':'deleteDeployment')}</h2><p><strong>{deleteTarget.name}</strong></p><p className="delete-explanation">{t(deleteTarget.kind==='project'?'removeProjectHint':'deleteDeploymentHint')}</p><div className="modal-actions"><Button variant="secondary" disabled={disabled} onClick={()=>setDeleteTarget(null)}>{t('cancel')}</Button><Button className="danger" disabled={disabled} onClick={removeRecord}>{t('confirmRemove')}</Button></div></Modal>}
  {questionsOpen&&<Modal title={t('questionsTitle')} onClose={()=>{if(busy!=='questions')setQuestionsOpen(false)}}><h2>{t('questionsTitle')}</h2><p>{t('questionsHint')}</p>{busy==='questions'?<div className="question-loading" role="status"><LoaderCircle className="spin" size={25}/><p>{t('questionsLoading')}</p></div>:<PlanningQuestions questions={questions} initial={choices.answers||{}} onSubmit={answerQuestions}/>}</Modal>}
  {approval&&plan&&<Modal title={t('approvalTitle')} onClose={()=>setApproval(null)}><div className="modal-symbol"><Rocket size={29}/></div><span className="eyebrow">{t('reviewChanges')}</span><h2>{t('approvalTitle')}</h2><p>{t('approvalDescription')}</p><div className="approval-cost"><span>{t('estimate')}</span><strong>{money(approval.monthlyPrice)} <small>{t('toman')}{t('month')}</small></strong></div><ol className="approval-actions">{approval.actions.map((a,i)=><li key={i}>{a}</li>)}</ol><p className="fine-print">{t('dontClose')} {t('expires')}</p><div className="modal-actions"><Button variant="secondary" onClick={()=>setApproval(null)}>{t('cancel')}</Button><Button disabled={disabled} onClick={deploy}>{disabled?<LoaderCircle size={16} className="spin"/>:<Rocket size={16}/>} {t(resumeId?'approveResume':'approve')}</Button></div></Modal>}
 </div>
}

function PageHeading({eyebrow,title,description}:{eyebrow:string;title:string;description:string}){return <div className="page-heading"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p dir="auto">{description}</p></div>}
function ConnectView({onConnect,onExternal,busy}:{onConnect:(token:string,teamId:string|undefined,remember:boolean)=>void;onExternal:(url:string)=>void;busy:boolean}){
 const {t}=useTranslation();const [token,setToken]=useState('');const [teamId,setTeamId]=useState('');const [visible,setVisible]=useState(false);const [remember,setRemember]=useState(true);const [privacy,setPrivacy]=useState(localStorage.getItem('liara-privacy')==='yes');const [guide,setGuide]=useState<'token'|'team'|null>(null);
 return <><div className="hero"><div className="hero-copy"><span className="eyebrow"><span/>{t('eyebrow')}</span><h1>{t('heroTitle').split('\n').map((line,i)=><span key={line} className={i===1?'accent':''}>{line}<br/></span>)}</h1><p>{t('heroDescription')}</p><div className="hero-meta"><span className="pill green"><ShieldCheck size={13}/>{t('control')}</span><span className="tiny-dot"/>Linux desktop</div></div><div className="launch-illustration" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><span className="orbit-dot dot-one"/><span className="orbit-dot dot-two"/><div className="cloud-center"><Cloud size={66} strokeWidth={1.4}/><span><Check size={14}/></span></div><div className="floating-card code-card"><span className="floating-icon"><Code2 size={22}/></span><div><i/><i/><i/></div></div><div className="floating-card live-card"><span className="mini-check"><Check size={15}/></span><div><strong>Ready to launch</strong><span>your-idea.liara.run</span></div></div><span className="illustration-star star-one">✦</span><span className="illustration-star star-two">✦</span></div></div>
 <section className="connect-panel panel"><div className="connect-heading"><div className="connect-icon"><KeyRound size={23}/></div><div><h2>{t('connectTitle')}</h2><p>{t('connectDescription')}</p></div><span className="step-label">01</span></div><div className="connect-body"><div className="guide-list"><button className="video-card" onClick={()=>setGuide('token')}><div className="video-thumbnail"><div className="mini-console"><Logo small/><i/><i/><i/><div><span>API TOKEN</span><b>••••••••••••</b></div></div><span className="play-button"><svg viewBox="0 0 20 20" width="18" height="18"><path d="M6 3l11 7-11 7z" fill="currentColor"/></svg></span><span className="video-time">GUIDE</span></div><strong>{t('tokenGuide')}<ArrowUpRight size={15}/></strong><span>{t('watchGuide')}</span></button><button className="video-card" onClick={()=>setGuide('team')}><div className="video-thumbnail team-id-thumbnail"><span className="team-id-mark">teamID</span><span className="play-button"><svg viewBox="0 0 20 20" width="18" height="18"><path d="M6 3l11 7-11 7z" fill="currentColor"/></svg></span><span className="video-time">GUIDE</span></div><strong>{t('teamIdGuide')}<ArrowUpRight size={15}/></strong><span>{t('teamIdWatchGuide')}</span></button></div><form className="token-form" onSubmit={e=>{e.preventDefault();localStorage.setItem('liara-privacy','yes');onConnect(token,teamId.trim()||undefined,remember);setToken('')}}><label htmlFor="teamId">{t('teamIdLabel')}</label><input id="teamId" dir="ltr" autoComplete="off" spellCheck={false} placeholder={t('teamIdPlaceholder')} value={teamId} onChange={e=>setTeamId(e.target.value)}/><p className="team-id-help">{t('teamIdHint')}</p><label htmlFor="token">{t('tokenLabel')}</label><div className="password-input"><LockKeyhole size={17}/><input id="token" type={visible?'text':'password'} dir="ltr" autoComplete="off" spellCheck={false} placeholder={t('tokenPlaceholder')} value={token} onChange={e=>setToken(e.target.value)} required/><button type="button" className="icon-button" onClick={()=>setVisible(!visible)} aria-label={t(visible?'hideToken':'showToken')}>{visible?<EyeOff size={17}/>:<Eye size={17}/>}</button></div><label className="checkbox-label"><input type="checkbox" checked={remember} onChange={e=>setRemember(e.target.checked)}/>{t('remember')}</label><div className="privacy-disclosure"><p>{t('privacy')}</p><label className="checkbox-label"><input type="checkbox" checked={privacy} onChange={e=>setPrivacy(e.target.checked)}/>{t('privacyAccept')}</label></div><Button type="submit" className="connect-submit" disabled={busy||!token.trim()||!privacy}>{busy?<LoaderCircle size={17} className="spin"/>:<Link2 size={17}/>} {t(busy?'connecting':'connectButton')}{!busy&&<ArrowRight size={17}/>}</Button><button type="button" className="text-button console-link" onClick={()=>onExternal('https://console.liara.ir/')}>{t('openConsole')}<ExternalLink size={13}/></button></form></div><div className="connect-security"><ShieldCheck size={15}/>{t('tokenSecurity')}</div></section>
 <div className="feature-grid">{[{icon:ShieldCheck,title:'secure',description:'secureDesc'},{icon:Workflow,title:'control',description:'controlDesc'},{icon:Layers3,title:'stack',description:'stackDesc'}].map(f=><div key={f.title}><f.icon size={20}/><h3>{t(f.title)}</h3><p>{t(f.description)}</p></div>)}</div>
 {guide&&<Modal title={t(guide==='team'?'teamIdGuide':'tokenGuide')} onClose={()=>setGuide(null)}><h2>{t(guide==='team'?'teamIdGuide':'tokenGuide')}</h2><p>{t(guide==='team'?'teamIdWatchGuide':'watchGuide')}</p><video className="tutorial-video" src={guide==='team'?'/reach-team-id-using-console.mp4':'/get-liara-api.mp4'} controls autoPlay playsInline aria-label={t(guide==='team'?'teamIdGuide':'tokenGuide')}/><button className="text-button" onClick={()=>onExternal('https://console.liara.ir/')}>{t('openConsole')}<ExternalLink size={14}/></button></Modal>}
 </>
}
function ServiceCard({service:s,account,choice,onEdit,money,locked}:{service:ServicePlan;account:Account;choice?:ServiceChoice;onEdit:(patch:Partial<ServiceChoice>)=>void;money:(n:number|null)=>string;locked:boolean}){
 const {t}=useTranslation();const resources=s.kind==='database'?account.databases:s.kind==='bucket'?account.buckets:account.projects;
 const plans=account.plans.filter(p=>p.category===s.kind&&(!p.supports.length||p.supports.includes(s.platform)));const volumes=s.volumes||[];
 const chooseVolume=(v:VolumeMount,resolution:string)=>{
  const prior=choice?.volumes?.[v.id]||{};
  const defaultName=`${s.name}-${v.target.split('/').filter(Boolean).at(-1)||'data'}`.toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,50);
  onEdit({volumes:{...(choice?.volumes||{}),[v.id]:{...prior,resolution,...(resolution==='disk'?{diskName:prior.diskName||defaultName,sizeGb:prior.sizeGb||5}:{})}}});
 };
 const setDisk=(v:VolumeMount,patch:{diskName?:string;sizeGb?:number})=>onEdit({volumes:{...(choice?.volumes||{}),[v.id]:{...(choice?.volumes?.[v.id]||{}),resolution:'disk',...patch}}});
 return <section className="panel service-card">
  <div className="service-heading"><PlatformIcon kind={s.kind} platform={s.platform}/><div><h3>{s.name}</h3><span className="platform-name">{s.platform}</span></div><span className="pill neutral">{s.kind==='database'?<Database size={12}/>:<Server size={12}/>} {t(s.kind==='database'?'services':'stepProject')}</span></div>
  <p className="service-rationale">{s.rationale}</p>
  <div className="form-grid"><label>{t('resourceName')}<input dir="ltr" value={choice?.name??s.name} disabled={locked||!!s.existingId} onChange={e=>onEdit({name:e.target.value})}/></label><label>{t('existingResource')}<Select value={choice?.existingId||''} disabled={locked} onChange={e=>{const r=resources.find(r=>String(r._id||r.DBId||r.id||r.project_id)===e.target.value);onEdit({existingId:e.target.value||undefined,...(r?{name:String(r.project_id||r.hostname||r.name)}:{})})}}><option value="">{t('newResource')}</option>{resources.filter(r=>!r.type||r.type===s.platform).map(r=><option key={String(r._id||r.DBId||r.id||r.project_id)} value={String(r._id||r.DBId||r.id||r.project_id)}>{String(r.project_id||r.hostname||r.name)}</option>)}</Select></label></div>
  {!choice?.existingId&&<label className="plan-select-label">{t('changePlan')}<Select value={`${choice?.planId??s.planId}|${choice?.bundleId??s.bundleId}`} disabled={locked} onChange={e=>{const [planId,bundleId]=e.target.value.split('|');onEdit({planId,bundleId,planLocked:true})}}>{plans.map(p=><option key={`${p.id}-${p.bundleId}`} value={`${p.id}|${p.bundleId}`}>{p.label} {p.bundleId&&`· ${p.bundleId}`} · {p.ram} GB RAM · {p.cpu} CPU · {money(p.monthlyPrice)} {t('toman')}</option>)}</Select></label>}
  <div className="resource-specs">{(()=>{const p=plans.find(p=>p.id===(choice?.planId??s.planId)&&p.bundleId===(choice?.bundleId??s.bundleId));return <><span><Server size={14}/>{p?.ram||'—'} GB RAM</span><span><Workflow size={14}/>{p?.cpu||'—'} CPU</span><span><Database size={14}/>{p?.disk||'—'} GB SSD</span></>})()}</div>
  {volumes.length>0&&<div className="volume-resolutions"><div className="volume-heading"><Database size={17}/><strong>{t('composeStorage')}</strong></div><p>{t('composeStorageHint')}</p>{volumes.filter(v=>!(v.kind==='bind'&&v.source==='.') ).map(v=>{const volumeChoice=choice?.volumes?.[v.id];const resolution=volumeChoice?.resolution||v.resolution||'';return <div className="volume-resolution" key={v.id}>
   <div className="volume-path"><code dir="ltr">{v.source||t('anonymousVolume')} → {v.target}</code><span>{v.readOnly?t('readOnly'):v.kind==='bind'?t('localFolder'):t('namedVolume')}</span></div>
   <label>{t('volumeAction')}<Select value={resolution} disabled={locked} onChange={e=>chooseVolume(v,e.target.value)}><option value="">{t('chooseVolumeAction')}</option>{v.kind==='bind'&&v.readOnly&&<option value="copy">{t('copyIntoImage')}</option>}<option value="disk">{t('persistentDisk')}</option><option value="temporary">{t('temporaryStorage')}</option></Select></label>
   {resolution==='disk'&&<div className="form-grid volume-disk-fields"><label>{t('diskName')}<input dir="ltr" value={volumeChoice?.diskName??v.diskName??''} disabled={locked} onChange={e=>setDisk(v,{diskName:e.target.value})}/></label><label>{t('diskSize')}<input type="number" min={1} max={1000} value={volumeChoice?.sizeGb??v.sizeGb??5} disabled={locked} onChange={e=>setDisk(v,{sizeGb:Number(e.target.value)})}/></label><p className="fine-print">{t('diskCreateApproval')}</p></div>}
   {resolution==='temporary'&&<p className="volume-warning">{t('temporaryStorageWarning')}</p>}
   {resolution==='copy'&&<p className="fine-print">{t('copyIntoImageHint')}</p>}
  </div>})}</div>}
  <details className="advanced-config"><summary>{t('configuration')}<ChevronDown size={15}/></summary><div className="form-grid">{s.kind==='app'?<label>{t('port')}<input type="number" min={1} max={65535} value={choice?.port??s.port} disabled={locked||s.files.some(f=>f.path==='liara-start.py')} onChange={e=>onEdit({port:Number(e.target.value)})}/></label>:<label>{t('version')}<input value={choice?.version??s.version??''} disabled={locked} onChange={e=>onEdit({version:e.target.value})}/></label>}</div>{s.files.map(f=><div className="config-file" key={f.path}><div><FileCode2 size={14}/><strong>{f.path}</strong><span>{t('stagingOnly')}</span></div><pre dir="ltr">{f.content}</pre></div>)}</details>
 </section>
}
function SettingsView({account,status,theme,setTheme,money,disconnect}:{account:Account|null;status?:AppStatus;theme:string;setTheme:(t:string)=>void;money:(n:number|null)=>string;disconnect:()=>void}){const {t,i18n}=useTranslation();return <><PageHeading eyebrow={t('settings')} title={t('settingsTitle')} description={t('settingsDescription')}/><section className="panel settings-panel"><div className="section-title"><Monitor size={21}/><h3>{t('appearance')}</h3></div><div className="setting-row"><span>{t('language')}</span><div className="segmented"><button className={i18n.language==='en'?'selected':''} onClick={()=>i18n.changeLanguage('en')}>English</button><button className={i18n.language==='fa'?'selected':''} onClick={()=>i18n.changeLanguage('fa')}>فارسی</button></div></div><div className="setting-row"><span>{t('theme')}</span><div className="segmented"><button className={theme==='light'?'selected':''} onClick={()=>setTheme('light')}><Sun size={15}/>{t('light')}</button><button className={theme==='dark'?'selected':''} onClick={()=>setTheme('dark')}><Moon size={15}/>{t('dark')}</button></div></div></section><section className="panel settings-panel"><div className="section-title"><Sparkles size={21}/><h3>{t('provider')}</h3><span className={`pill ${status?.agent.configured?'green':'amber'}`}>{t(status?.agent.configured?'configured':'notConfigured')}</span></div>{status?.agent.configured?<><div className="setting-row"><span>{t('model')}</span><code>{status.agent.model}</code></div><div className="setting-row"><span>{t('endpoint')}</span><code>{status.agent.baseUrl}</code></div></>:<><p>{t('providerSetup')}</p><pre dir="ltr" className="env-example">OPENAI_BASE_URL=https://your-provider/v1{'\n'}OPENAI_MODEL=your-model{'\n'}OPENAI_API_KEY=your-key</pre></>}<p className="fine-print">{t('providerDetails')}</p></section>{account&&<section className="panel settings-panel"><div className="section-title"><Cloud size={21}/><h3>{t('account')}</h3><span className="pill green">{t('connected')}</span></div><div className="setting-row"><div><strong>{account.name}</strong><p>{account.email}</p></div><Button variant="secondary" onClick={disconnect}><LogOut size={15}/>{t('disconnect')}</Button></div><div className="setting-row"><span>{t('balance')}</span><strong>{money(account.balance)} {t('toman')}</strong></div><p className="fine-print"><LockKeyhole size={14}/>{t(account.credentialStorage==='keyring'?'keyring':'sessionOnly')}</p>{account.warnings.map((w,i)=><Notice key={i}>{w}</Notice>)}</section>}<section className="privacy-setting"><ShieldCheck size={26}/><div><h3>{t('privacyTitle')}</h3><p>{t('privacyDetails')}</p></div></section></>}
function DomainPanel({run,work,busy}:{run:DeploymentRun;work:(label:string,fn:()=>Promise<void>)=>Promise<void>;busy:string}){const {t}=useTranslation();const [domain,setDomain]=useState('');const [manageDns,setManageDns]=useState(false);const [service,setService]=useState(run.plan.services.find(s=>s.kind==='app')?.id||'');const [request,setRequest]=useState<DomainRequest|null>(null);const [result,setResult]=useState<DomainResult|null>(null);const prepare=()=>work('domain',async()=>{setRequest(await call<DomainRequest>('prepare_domain',{runId:run.id,serviceId:service,domain,manageDns}))});return <section className="panel domain-panel"><div className="section-title"><Globe2 size={21}/><h3>{t('customDomain')}</h3></div><p>{t('domainDescription')}</p><div className="form-grid"><label>{t('domainLabel')}<input dir="ltr" placeholder={t('domainPlaceholder')} value={domain} onChange={e=>setDomain(e.target.value)}/></label><label>{t('services')}<Select value={service} onChange={e=>setService(e.target.value)}>{run.plan.services.filter(s=>s.kind==='app').map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</Select></label></div><label className="checkbox-label"><input type="checkbox" checked={manageDns} onChange={e=>setManageDns(e.target.checked)}/>{t('dnsManaged')}</label><Button variant="secondary" disabled={!domain||!!busy} onClick={prepare}><Globe2 size={16}/>{t(result?'checkAgain':'prepareDomain')}</Button>{result&&<div className="domain-result"><span className="eyebrow">{t('domainTarget')}</span><div><code dir="ltr">{result.target}</code><button className="icon-button" aria-label="Copy CNAME" onClick={()=>navigator.clipboard.writeText(result.target)}><Copy size={16}/></button></div><p>{t('domainStatus')}: {result.status}</p><p>{t('domainExternal')}</p><span className={`pill ${result.tls.requested?'green':'amber'}`}>{t(result.tls.requested?'tlsRequested':'tlsPending')}</span>{result.tls.error&&<Notice>{result.tls.error}</Notice>}</div>}{request&&<Modal title={t('prepareDomain')} onClose={()=>setRequest(null)}><div className="modal-symbol"><Globe2 size={27}/></div><h2>{t('prepareDomain')}</h2><p><strong dir="ltr">{request.domain}</strong> → {request.projectName}</p><ol className="approval-actions">{request.actions.map(a=><li key={a}>{a}</li>)}</ol><div className="modal-actions"><Button variant="secondary" onClick={()=>setRequest(null)}>{t('cancel')}</Button><Button disabled={!!busy} onClick={()=>work('domain',async()=>{setResult(await call<DomainResult>('apply_domain',{approvalId:request.id}));setRequest(null)})}>{t('applyDomain')}</Button></div></Modal>}</section>}

function PlanningQuestions({questions,initial,onSubmit}:{questions:PlanningQuestion[];initial:Record<string,string>;onSubmit:(answers:Record<string,string>)=>void}){
 const {t}=useTranslation();const [answers,setAnswers]=useState<Record<string,string>>(initial);
 return <form className="planning-questions" onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(questions.map(q=>[q.id,answers[q.id]?.trim()||t('unsure')])));}}>
 {questions.map((q,index)=><label key={q.id} htmlFor={`question-${q.id}`}><strong>{index+1}. {q.question}</strong><span>{q.hint}</span>{q.options.length?<Select id={`question-${q.id}`} required value={answers[q.id]||''} onChange={e=>setAnswers(a=>({...a,[q.id]:e.target.value}))}><option value="" disabled>{t('chooseAnswer')}</option>{[...new Set([...q.options,t('unsure')])].map(option=><option key={option}>{option}</option>)}</Select>:<input id={`question-${q.id}`} required maxLength={1000} value={answers[q.id]||''} onChange={e=>setAnswers(a=>({...a,[q.id]:e.target.value}))} placeholder={t('answerPlaceholder')}/>}</label>)}
 <p className="fine-print">{t('questionsPrivacy')}</p><div className="modal-actions"><Button type="submit" disabled={!questions.length||questions.some(q=>!answers[q.id]?.trim())}><Sparkles size={16}/>{t('createPlan')}</Button></div></form>
}
